	public bool Show_AddAIPanel
	{
		get
		{
			return _Show_AddAI;
		}
		set
		{
			if (_Show_AddAI != value)
			{
				_Show_AddAI = value;
				NotifyPropertyChanged("Show_AddAIPanel");
			}
			if (!value)
			{
				if (FRONT_Multiplayer.skirmishGame || (FRONTMultiplayer.currentLobby != null && FRONTMultiplayer.currentLobby.isHost))
				{
					FRONTMultiplayer.RefMultiplayerPlayButton.Visibility = Visibility.Visible;
				}
				Show_SkirmishAIADD = FRONT_Multiplayer.skirmishGame || (FRONTMultiplayer.currentLobby != null && FRONTMultiplayer.currentLobby.isHost);
				Show_SkirmishRandomAI = FRONT_Multiplayer.skirmishGame;
				Show_SkirmishTeams = FRONT_Multiplayer.skirmishGame || !FRONT_Multiplayer.customCoopGame;
			}
			else
			{
				FRONTMultiplayer.RefMultiplayerPlayButton.Visibility = Visibility.Hidden;
				Show_SkirmishAIADD = false;
				Show_SkirmishRandomAI = false;
				Show_SkirmishTeams = false;
			}
		}
	}

