	public void InitDLCAILordVisibility()
	{
		for (int i = 0; i < 9; i++)
		{
			switch (i)
			{
			case 0:
			case 1:
				if (FrontendMenus.DLC1Owned)
				{
					NewAILordVisible.Add(Visibility.Hidden);
					NewAILordNotVisible.Add(Visibility.Visible);
				}
				else
				{
					NewAILordVisible.Add(Visibility.Visible);
					NewAILordNotVisible.Add(Visibility.Hidden);
				}
				break;
			case 2:
			case 3:
				if (FrontendMenus.DLC2Owned)
				{
					NewAILordVisible.Add(Visibility.Hidden);
					NewAILordNotVisible.Add(Visibility.Visible);
				}
				else
				{
					NewAILordVisible.Add(Visibility.Visible);
					NewAILordNotVisible.Add(Visibility.Hidden);
				}
				break;
			case 5:
			case 6:
				if (FrontendMenus.DLC3Owned)
				{
					NewAILordVisible.Add(Visibility.Hidden);
					NewAILordNotVisible.Add(Visibility.Visible);
				}
				else
				{
					NewAILordVisible.Add(Visibility.Visible);
					NewAILordNotVisible.Add(Visibility.Hidden);
				}
				break;
			case 7:
			case 8:
				if (FrontendMenus.DLC4Owned)
				{
					NewAILordVisible.Add(Visibility.Hidden);
					NewAILordNotVisible.Add(Visibility.Visible);
				}
				else
				{
					NewAILordVisible.Add(Visibility.Visible);
					NewAILordNotVisible.Add(Visibility.Hidden);
				}
				break;
			default:
				NewAILordNotVisible.Add(Visibility.Collapsed);
				NewAILordVisible.Add(Visibility.Collapsed);
				break;
			}
		}
	}

