	private void ButtonCreateTroop(object parameter)
	{
		Enums.eChimps chimpEnum = getChimpEnum(parameter as string);
		bool flag = true;
		switch (chimpEnum)
		{
		case Enums.eChimps.CHIMP_TYPE_ARCHER:
			if (GameData.Instance.lastGameState.troop_types_available[0] <= 0 && HUDBuildingPanel.RefRecruitArcherButton.IsEnabled)
			{
				flag = false;
			}
			break;
		case Enums.eChimps.CHIMP_TYPE_SPEARMAN:
			if (GameData.Instance.lastGameState.troop_types_available[2] <= 0 && HUDBuildingPanel.RefRecruitSpearmanButton.IsEnabled)
			{
				flag = false;
			}
			break;
		case Enums.eChimps.CHIMP_TYPE_MACEMAN:
			if (GameData.Instance.lastGameState.troop_types_available[4] <= 0 && HUDBuildingPanel.RefRecruitMacemanButton.IsEnabled)
			{
				flag = false;
			}
			break;
		case Enums.eChimps.CHIMP_TYPE_SWORDSMAN:
			if (GameData.Instance.lastGameState.troop_types_available[5] <= 0 && HUDBuildingPanel.RefRecruitSwordsmanButton.IsEnabled)
			{
				flag = false;
			}
			break;
		case Enums.eChimps.CHIMP_TYPE_XBOWMAN:
			if (GameData.Instance.lastGameState.troop_types_available[1] <= 0 && HUDBuildingPanel.RefRecruitXBowmanButton.IsEnabled)
			{
				flag = false;
			}
			break;
		case Enums.eChimps.CHIMP_TYPE_PIKEMAN:
			if (GameData.Instance.lastGameState.troop_types_available[3] <= 0 && HUDBuildingPanel.RefRecruitPikemanButton.IsEnabled)
			{
				flag = false;
			}
			break;
		case Enums.eChimps.CHIMP_TYPE_KNIGHT:
			if (GameData.Instance.lastGameState.troop_types_available[6] <= 0 && HUDBuildingPanel.RefRecruitKnightButton.IsEnabled)
			{
				flag = false;
			}
			break;
		case Enums.eChimps.CHIMP_TYPE_LADDERMAN:
			if (!HUDBuildingPanel.RefRecruitLaddermanButton.IsEnabled)
			{
				flag = false;
			}
			break;
		case Enums.eChimps.CHIMP_TYPE_ENGINEER:
			if (!HUDBuildingPanel.RefRecruitEngineerButton.IsEnabled)
			{
				flag = false;
			}
			break;
		case Enums.eChimps.CHIMP_TYPE_ARAB_BOW:
			if (GameData.Instance.lastGameState.merc_troop_types_available[0] <= 0 && HUDBuildingPanel.RefRecruitArabBowButton.IsEnabled)
			{
				flag = false;
			}
			break;
		case Enums.eChimps.CHIMP_TYPE_ARAB_SLAVE:
			if (GameData.Instance.lastGameState.merc_troop_types_available[1] <= 0 && HUDBuildingPanel.RefRecruitArabSlaveButton.IsEnabled)
			{
				flag = false;
			}
			break;
		case Enums.eChimps.CHIMP_TYPE_ARAB_SLINGER:
			if (GameData.Instance.lastGameState.merc_troop_types_available[2] <= 0 && HUDBuildingPanel.RefRecruitArabSlingerButton.IsEnabled)
			{
				flag = false;
			}
			break;
		case Enums.eChimps.CHIMP_TYPE_ARAB_ASSASIN:
			if (GameData.Instance.lastGameState.merc_troop_types_available[3] <= 0 && HUDBuildingPanel.RefRecruitArabAssassinButton.IsEnabled)
			{
				flag = false;
			}
			break;
		case Enums.eChimps.CHIMP_TYPE_ARAB_HORSEMAN:
			if (GameData.Instance.lastGameState.merc_troop_types_available[4] <= 0 && HUDBuildingPanel.RefRecruitArabHorseArcherButton.IsEnabled)
			{
				flag = false;
			}
			break;
		case Enums.eChimps.CHIMP_TYPE_ARAB_SWORDSMAN:
			if (GameData.Instance.lastGameState.merc_troop_types_available[5] <= 0 && HUDBuildingPanel.RefRecruitArabSwordsmanButton.IsEnabled)
			{
				flag = false;
			}
			break;
		case Enums.eChimps.CHIMP_TYPE_ARAB_GRENADIER:
			if (GameData.Instance.lastGameState.merc_troop_types_available[6] <= 0 && HUDBuildingPanel.RefRecruitArabGrenadierButton.IsEnabled)
			{
				flag = false;
			}
			break;
		case Enums.eChimps.CHIMP_TYPE_BEDOUIN_CAMEL_LANCER:
			if (GameData.Instance.lastGameState.bed_troop_types_available[0] <= 0 && HUDBuildingPanel.RefRecruitBedouinCamelLancerButton.IsEnabled)
			{
				flag = false;
			}
			break;
		case Enums.eChimps.CHIMP_TYPE_BEDOUIN_HEALER:
			if (GameData.Instance.lastGameState.bed_troop_types_available[1] <= 0 && HUDBuildingPanel.RefRecruitBedouinHealerButton.IsEnabled)
			{
				flag = false;
			}
			break;
		case Enums.eChimps.CHIMP_TYPE_BEDOUIN_EUNUCH:
			if (GameData.Instance.lastGameState.bed_troop_types_available[2] <= 0 && HUDBuildingPanel.RefRecruitBedouinEunuchButton.IsEnabled)
			{
				flag = false;
			}
			break;
		case Enums.eChimps.CHIMP_TYPE_BEDOUIN_AMBUSHER:
			if (GameData.Instance.lastGameState.bed_troop_types_available[3] <= 0 && HUDBuildingPanel.RefRecruitBedouinAmbusherButton.IsEnabled)
			{
				flag = false;
			}
			break;
		case Enums.eChimps.CHIMP_TYPE_BEDOUIN_SKIRMISHER:
			if (GameData.Instance.lastGameState.bed_troop_types_available[4] <= 0 && HUDBuildingPanel.RefRecruitBedouinSkirmisherButton.IsEnabled)
			{
				flag = false;
			}
			break;
		case Enums.eChimps.CHIMP_TYPE_BEDOUIN_HEAVY_CAMEL:
			if (GameData.Instance.lastGameState.bed_troop_types_available[5] <= 0 && HUDBuildingPanel.RefRecruitBedouinHeavyCamelButton.IsEnabled)
			{
				flag = false;
			}
			break;
		case Enums.eChimps.CHIMP_TYPE_BEDOUIN_SAPPER:
			if (GameData.Instance.lastGameState.bed_troop_types_available[6] <= 0 && HUDBuildingPanel.RefRecruitBedouinSapperButton.IsEnabled)
			{
				flag = false;
			}
			break;
		case Enums.eChimps.CHIMP_TYPE_BEDOUIN_DEMOLISHER:
			if (GameData.Instance.lastGameState.bed_troop_types_available[7] <= 0 && HUDBuildingPanel.RefRecruitBedouinDemolisherButton.IsEnabled)
			{
				flag = false;
			}
			break;
		default:
		{
			Enums.eMappers mapperEnum = getMapperEnum(parameter as string);
			if ((uint)(mapperEnum - 332) <= 6u || (uint)(mapperEnum - 360) <= 10u || (uint)(mapperEnum - 391) <= 7u)
			{
				flag = false;
				EditorDirector.instance.placeBuildingInteraction(mapperEnum);
			}
			break;
		}
		}
		if (flag)
		{
			int structureID = 1;
			if (KeyManager.instance.isShiftDown())
			{
				structureID = 5;
			}
			else if (KeyManager.instance.isCtrlDown())
			{
				structureID = 1000;
			}
			EngineInterface.GameAction(Enums.GameActionCommand.MakeTroop, structureID, (int)chimpEnum);
		}
	}

	private void setCreateTroopText()
	{
		TroopNameCostText = Translate.Instance.lookUpText(Enums.eTextSections.TEXT_CHIMP_NAMES, (int)lastTroopBuildChimp);
		TroopCostText = " " + GameData.getChimpGoldCost((int)lastTroopBuildChimp) * lastTroopsAmountToMake + "  ";
		if (lastTroopsAmountToMake > 1)
		{
			TroopNameCostText = TroopNameCostText + " x" + lastTroopsAmountToMake;
		}
		TroopNameCostText2 = "[" + Translate.Instance.lookUpText(Enums.eTextSections.TEXT_HOT_KEYS, 78).ToUpper() + "] x" + lastTroopsAmountToMakex5 + "   [" + Translate.Instance.lookUpText(Enums.eTextSections.TEXT_HOT_KEYS, 79).ToUpper() + "] x" + lastTroopsAmountToMakeMax;
	}

	public void ButtonEnterCreateTroop(object parameter)
	{
		string text = (lastTroopBuildOver = parameter as string);
		lastTroopBuildChimp = Enums.eChimps.CHIMP_NUM_TYPES;
		Visibility visibility = Visibility.Visible;
		Visibility visibility2 = Visibility.Hidden;
		Visibility visibility3 = Visibility.Visible;
		Visibility visibility4 = Visibility.Hidden;
		Visibility visibility5 = Visibility.Visible;
		Visibility visibility6 = Visibility.Hidden;
		Visibility visibility7 = Visibility.Visible;
		Visibility visibility8 = Visibility.Hidden;
		switch (text)
		{
		case "Archer":
			if (GameData.Instance.lastGameState.troop_types_available[0] > 0)
			{
				HUDBuildingPanel.RefRecruitArcherButton.IsChecked = true;
				lastTroopBuildChimp = Enums.eChimps.CHIMP_TYPE_ARCHER;
				Show_BarracksBows2 = true;
				setCreateTroopText();
				if (!Director.instance.MultiplayerGame || GameData.Instance.lastGameState.MP_TroopsCostGold)
				{
					HUDBuildingPanel.RefTroopCostsText.Visibility = Visibility.Visible;
				}
			}
			break;
		case "Spearman":
			if (GameData.Instance.lastGameState.troop_types_available[2] > 0)
			{
				HUDBuildingPanel.RefRecruitSpearmanButton.IsChecked = true;
				lastTroopBuildChimp = Enums.eChimps.CHIMP_TYPE_SPEARMAN;
				Show_BarracksSpears2 = true;
				setCreateTroopText();
				if (!Director.instance.MultiplayerGame || GameData.Instance.lastGameState.MP_TroopsCostGold)
				{
					HUDBuildingPanel.RefTroopCostsText.Visibility = Visibility.Visible;
				}
			}
			break;
		case "Maceman":
			if (GameData.Instance.lastGameState.troop_types_available[4] > 0)
			{
				HUDBuildingPanel.RefRecruitMacemanButton.IsChecked = true;
				lastTroopBuildChimp = Enums.eChimps.CHIMP_TYPE_MACEMAN;
				Show_BarracksMaces2 = true;
				Show_BarracksLeatherArmour2 = true;
				setCreateTroopText();
				if (!Director.instance.MultiplayerGame || GameData.Instance.lastGameState.MP_TroopsCostGold)
				{
					HUDBuildingPanel.RefTroopCostsText.Visibility = Visibility.Visible;
				}
			}
			break;
		case "XBowman":
			if (GameData.Instance.lastGameState.troop_types_available[1] > 0)
			{
				HUDBuildingPanel.RefRecruitXBowmanButton.IsChecked = true;
				lastTroopBuildChimp = Enums.eChimps.CHIMP_TYPE_XBOWMAN;
				Show_BarracksXBows2 = true;
				Show_BarracksLeatherArmour2 = true;
				setCreateTroopText();
				if (!Director.instance.MultiplayerGame || GameData.Instance.lastGameState.MP_TroopsCostGold)
				{
					HUDBuildingPanel.RefTroopCostsText.Visibility = Visibility.Visible;
				}
			}
			break;
		case "Pikeman":
			if (GameData.Instance.lastGameState.troop_types_available[3] > 0)
			{
				HUDBuildingPanel.RefRecruitPikemanButton.IsChecked = true;
				lastTroopBuildChimp = Enums.eChimps.CHIMP_TYPE_PIKEMAN;
				Show_BarracksPikes2 = true;
				Show_BarracksArmour2 = true;
				setCreateTroopText();
				if (!Director.instance.MultiplayerGame || GameData.Instance.lastGameState.MP_TroopsCostGold)
				{
					HUDBuildingPanel.RefTroopCostsText.Visibility = Visibility.Visible;
				}
			}
			break;
		case "Swordsman":
			if (GameData.Instance.lastGameState.troop_types_available[5] > 0)
			{
				HUDBuildingPanel.RefRecruitSwordsmanButton.IsChecked = true;
				lastTroopBuildChimp = Enums.eChimps.CHIMP_TYPE_SWORDSMAN;
				Show_BarracksSwords2 = true;
