		case "Knight":
			if (GameData.Instance.lastGameState.troop_types_available[6] > 0)
			{
				HUDBuildingPanel.RefRecruitKnightButton.IsChecked = true;
				lastTroopBuildChimp = Enums.eChimps.CHIMP_TYPE_KNIGHT;
