		if (IsMapEditorMode || GameData.Instance.game_type == 4 || GameData.scenario.InGameoverSituation)
		{
			return;
		}
		ResizeBriefingScreen();
		BriefingFromStory = (string)parameter == "FromStory";
		Show_HUD_Main = false;
		Show_HUD_Troops = false;
		Show_HUD_Building = false;
