	public void SetVisibleState(bool state)
	{
		if (!state)
		{
			Show_InGameUI = false;
			UIVisible = false;
			Compass_Vis = false;
			Instance.ShowGameTime = Visibility.Collapsed;
			ShowLocalTime = Visibility.Collapsed;
			Show_HUD_Extreme = false;
			return;
		}
		UIVisible = true;
		Show_InGameUI = true;
		Compass_Vis = ConfigSettings.Settings_Compass || Instance.IsMapEditorMode;
		if (ConfigSettings.Settings_ShowGameTime && !Instance.IsMapEditorMode)
		{
			ShowGameTime = Visibility.Visible;
		}
		else
		{
			ShowGameTime = Visibility.Collapsed;
		}
		if (ConfigSettings.Settings_ShowLocalTime)
		{
			ShowLocalTime = Visibility.Visible;
		}
		else
		{
			ShowLocalTime = Visibility.Collapsed;
		}
	}

