		Instance.HUDIngameMenu.restartMapInfo = null;
		Instance.HUDIngameMenu.restartSkirmishMapInfo = null;
		Instance.HUDIngameMenu.restartMPInfo = null;
		startedMission = StoryChapter;
		EditorDirector.instance.LoadCampaignMap(StoryChapter, 1);
